export interface FixedWindowState { start: number; count: number }

export function fixedWindow(options: { limit: number; windowMs: number }): Algorithm<FixedWindowState> {
  const limit = options.limit;
  const window = options.windowMs;
  if (!Number.isFinite(limit) || limit <= 0) throw new RateLimitError("limit must be a positive number");
  if (!Number.isInteger(window) || window <= 0) throw new RateLimitError("windowMs must be a positive integer");
  return {
    name: "fixed-window",
    limit,
    luaFile: "fixed_window_kit.lua",
    args: () => [String(limit), String(window)],
    step(state, now, cost) {
      const start = now - (now % window);
      const count = state !== undefined && state.start === start ? state.count : 0;
      const resetMs = window - (now - start); // >= 1 because now - start < window
      if (count + cost > limit) {
        // denied: nothing counted (same rule as the sliding window)
        const decision: Decision = { allowed: false, limit, remaining: Math.max(Math.floor(limit - count), 0), retryAfterMs: resetMs, resetMs };
        return { state: state ?? { start, count: 0 }, decision };
      }
      const next = count + cost;
      const decision: Decision = { allowed: true, limit, remaining: Math.max(Math.floor(limit - next), 0), retryAfterMs: 0, resetMs };
      return { state: { start, count: next }, decision };
    },
  };
}

-- illustrative, NOT in the repo -- src/lua/fixed_window_kit.lua
-- KEYS[1] = base key; ARGV[1] = limit, ARGV[2] = window_ms, ARGV[3] = now_ms ('' => Redis TIME), ARGV[4] = cost
local limit = tonumber(ARGV[1])
local window = tonumber(ARGV[2])
local cost = tonumber(ARGV[4])
local now
if ARGV[3] == '' then
  local t = redis.call('TIME')
  now = tonumber(t[1]) * 1000 + math.floor(tonumber(t[2]) / 1000)
else
  now = tonumber(ARGV[3])
end
local start = now - (now % window)
local key = KEYS[1] .. ':' .. start
local count = tonumber(redis.call('GET', key) or '0')
local reset = window - (now - start)
if count + cost > limit then
  return {0, math.max(math.floor(limit - count), 0), reset, reset}
end
count = redis.call('INCRBY', key, cost)
redis.call('PEXPIRE', key, window)
return {1, math.max(math.floor(limit - count), 0), 0, reset}

