describe("fixed window", () => {
  const W = 60_000;
  it("allows limit per window, denies until the window ends, and shows the edge burst", async () => {
    let t = 10 * W + W - 1; // 1 ms before a window boundary
    const limiter = new RateLimiter({ algorithm: fixedWindow({ limit: 3, windowMs: W }), store: new MemoryStore({ now: () => t }) });
    for (let i = 2; i >= 0; i--) expect(await limiter.consume("a")).toMatchObject({ allowed: true, remaining: i });
    expect(await limiter.consume("a")).toMatchObject({ allowed: false, retryAfterMs: 1, resetMs: 1 });
    t += 1; // next window: the counter starts again -> 6 allowed within 2 ms (the edge burst)
    for (let i = 0; i < 3; i++) expect((await limiter.consume("a")).allowed).toBe(true);
    expect((await limiter.consume("a")).allowed).toBe(false);
  });
});
