// illustrative, NOT in the repo -- a per-route cost function for the Express adapter
import express from "express";
import type { IncomingMessage } from "node:http";
import { rateLimit } from "ratelimit-kit/express"; // in the repo: ../src/adapters/express.js
import { MemoryStore, RateLimiter, tokenBucket } from "ratelimit-kit";

const exportLimit = new RateLimiter({
  algorithm: tokenBucket({ capacity: 20, refillPerSec: 1 }),
  store: new MemoryStore(),
  prefix: "rl:export:",
});

// GET /export?rows=N costs 1 unit per started 100 rows, at least 1, at most the limit.
// Clamped: a cost above the limit would be a RateLimitError (a 500, never failed open).
export function exportCost(limit: number) {
  return (req: IncomingMessage): number => {
    const rows = Number(new URL(req.url ?? "/", "http://x").searchParams.get("rows") ?? "100");
    const units = Number.isFinite(rows) && rows > 0 ? Math.ceil(rows / 100) : 1;
    return Math.min(Math.max(units, 1), limit);
  };
}

export function buildApp() {
  const app = express();
  app.get("/export", (req, res, next) => {
    const rows = Number(req.query.rows ?? 100);
    if (rows > 2000) return res.status(413).json({ error: "too_many_rows" }); // reject BEFORE the limiter
    next();
  }, rateLimit(exportLimit, { cost: exportCost(exportLimit.limit) }), (_req, res) => res.json({ ok: true }));
  return app;
}

// illustrative, NOT in the repo -- test/export-cost.test.ts (vitest)
import { afterEach, describe, expect, it } from "vitest";
import type { Server } from "node:http";
import type { AddressInfo } from "node:net";

describe("per-route cost", () => {
  let server: Server | undefined;
  afterEach(() => new Promise<void>((r) => (server ? server.close(() => r()) : r())));

  it("maps rows to units", () => {
    const cost = exportCost(20);
    expect(cost({ url: "/export?rows=1" } as IncomingMessage)).toBe(1);
    expect(cost({ url: "/export?rows=250" } as IncomingMessage)).toBe(3);
    expect(cost({ url: "/export?rows=999999" } as IncomingMessage)).toBe(20); // clamped to the limit
    expect(cost({ url: "/export?rows=abc" } as IncomingMessage)).toBe(1);
  });

  it("a big export uses up the bucket faster", async () => {
    server = buildApp().listen(0, "127.0.0.1");
    await new Promise((r) => server!.once("listening", r));
    const base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
    const first = await fetch(`${base}/export?rows=1500`); // cost 15
    expect(first.status).toBe(200);
    expect(first.headers.get("ratelimit-remaining")).toBe("5");
    const second = await fetch(`${base}/export?rows=1000`); // cost 10 > 5 left
    expect(second.status).toBe(429);
    expect(Number(second.headers.get("retry-after"))).toBe(5); // 5 tokens at 1/s
  });
});

